package controlador;
import java.io.IOException; import jakarta.servlet.*; import jakarta.servlet.http.*; import modelo.Servicio; import modelo.ServicioDAO;
public class CtrolServicio extends HttpServlet {protected void processRequest(HttpServletRequest request,HttpServletResponse response)throws ServletException,IOException{request.setCharacterEncoding("UTF-8"); Servicio s=new Servicio(); String id=request.getParameter("id_servicio"); if(id!=null&&!id.isEmpty())s.setIdServicio(Integer.parseInt(id)); s.setNombreServicio(request.getParameter("nombre_servicio")); s.setDescripcion(request.getParameter("descripcion")); ServicioDAO dao=new ServicioDAO(); if(s.getIdServicio()>0)dao.editar(s); else dao.agregar(s); response.sendRedirect("listaServicios.jsp");} @Override protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{processRequest(r,s);} @Override protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{s.sendRedirect("listaServicios.jsp");}}
